syntax = "proto3";

package users;

service UsersService {
  rpc FindAll (Empty) returns (UserList);
}

message Empty {}

message User {
  int32 id = 1;
  string name = 2;
}

message UserList {
  repeated User users = 1;
}

import { NestFactory } from '@nestjs/core';
import { Transport } from '@nestjs/microservices';
import { join } from 'path';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.createMicroservice(AppModule, {
    transport: Transport.GRPC,
    options: {
      package: 'users',
      protoPath: join(__dirname, 'users.proto'),
      url: 'localhost:50051',
    },
  });
  await app.listen();
}
bootstrap();

import { Controller } from '@nestjs/common';
import { GrpcMethod } from '@nestjs/microservices';

@Controller()
export class UsersController {
  private users = [
    { id: 1, name: 'Minh' },
    { id: 2, name: 'Lan' },
  ];

  @GrpcMethod('UsersService', 'FindAll')
  findAll() {
    return { users: this.users };
  }
}

import { Module } from '@nestjs/common';
import { ClientsModule, Transport } from '@nestjs/microservices';
import { join } from 'path';
import { UsersController } from './users.controller';

@Module({
  imports: [
    ClientsModule.register([
      {
        name: 'USERS_PACKAGE',
        transport: Transport.GRPC,
        options: {
          package: 'users',
          protoPath: join(__dirname, 'users.proto'),
          url: 'localhost:50051',
        },
      },
    ]),
  ],
  controllers: [UsersController],
})
export class AppModule {}

import { Controller, Get, Inject, OnModuleInit } from '@nestjs/common';
import { ClientGrpc } from '@nestjs/microservices';
import { Observable } from 'rxjs';

interface UsersGrpcService {
  findAll(request: object): Observable<{ users: { id: number; name: string }[] }>;
}

@Controller('users')
export class UsersController implements OnModuleInit {
  private usersService: UsersGrpcService;

  constructor(@Inject('USERS_PACKAGE') private client: ClientGrpc) {}

  onModuleInit() {
    this.usersService = this.client.getService<UsersGrpcService>('UsersService');
  }

  @Get()
  findAll() {
    return this.usersService.findAll({});
  }
}
